const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const browser=await chromium.launch({args:['--no-sandbox']});try{const p=await browser.newPage({viewport:{width:390,height:844}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#homeTab');await p.evaluate(()=>window.speak=s=>window.testSpoken=s);
 if(await p.locator('#courseSearch').isVisible())throw Error('Search must start collapsed');await p.click('#courseSearchToggle');if(!await p.locator('#courseSearch').evaluate(el=>el===document.activeElement))throw Error('Search focus missing');await p.fill('#courseSearch','79.');if(await p.locator('#courseCatalog [data-cv2-open]:visible').count()!==1)throw Error('Search missing final lesson');await p.keyboard.press('Escape');if(await p.locator('#courseSearch').isVisible()||!await p.locator('#courseSearchToggle').evaluate(el=>el===document.activeElement))throw Error('Search Escape/focus broken');
 await p.evaluate(()=>{const d=DEUTSCH_COURSE_DATA;if(d.lessons.length!==79||d.lessons.some((l,i)=>l.number!==i+1||l.id==='sounds-greetings'||l.prerequisiteIds.includes('sounds-greetings')))throw Error('Course removal/renumbering failed');if(d.lessons[0].id!=='personal-pronouns'||document.querySelector('#newCourseStart').textContent.includes('Звуки, читання'))throw Error('Course starts with sounds');for(const x of DEUTSCH_SOUND_DATA.topics)if(!recordedAudioFiles(x.de))throw Error('Missing human word recording '+x.de);profileStorage.setItem('deutsch16_course_v2',JSON.stringify({'sounds-greetings':{best:90,completed:true}}));profileStorage.removeItem(DEUTSCH_SOUNDS.key);setMode('home');if(!document.querySelector('#newCourseStart').textContent.includes('0 із 79'))throw Error('Old introduction counted as grammar lesson')});
 await p.click('#soundsTab');if(await p.locator('.sound-grid .course-card').count()!==22)throw Error('Incomplete sound topics');if(!await p.locator('#courseLessonView').textContent().then(s=>s.includes('90%')))throw Error('Old introduction result lost');
 await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_SOUNDS.open()});if(await p.locator('#courseLessonView').textContent().then(s=>/[А-Яа-яІіЇїЄє]/.test(s)))throw Error('English sound explanations contain Ukrainian');await p.click('[data-sound-panel="phrases"]');if(await p.locator('#courseLessonView .course-card').count()!==8||!await p.locator('#courseLessonView').textContent().then(s=>s.includes('Good morning!')))throw Error('Greeting localization lost');
 async function complete(mode){await p.evaluate(m=>DEUTSCH_SOUNDS.start(m),mode);let n=0;while(await p.evaluate(()=>!!DEUTSCH_SOUNDS.snapshot())){if(++n>20)throw Error('Quiz did not finish');await p.click('[data-sound-listen]');await p.evaluate(()=>{const q=DEUTSCH_SOUNDS.snapshot();if(testSpoken!==q.items[q.at].de)throw Error('Wrong whole recording')});if(mode==='dictation'||await p.locator('#soundForm').count()){const de=await p.evaluate(()=>{const q=DEUTSCH_SOUNDS.snapshot();return q.items[q.at].de});await p.fill('#soundAnswer',de.replace(/ü/g,'ue'));await p.locator('#soundForm button').click()}else await p.evaluate(()=>{const q=DEUTSCH_SOUNDS.snapshot(),de=q.items[q.at].de;[...document.querySelectorAll('[data-sound-answer]')].find(b=>b.dataset.soundAnswer===de).click()});await p.evaluate(()=>{const q=DEUTSCH_SOUNDS.snapshot(),n=q.answers.length;DEUTSCH_SOUNDS.answer(q.items[q.at].de);if(q.answers.length!==n)throw Error('Double grading');if(!q.answers.at(-1))throw Error('Correct answer rejected')});await p.click('[data-sound-next]')};if(!await p.locator('#courseLessonView').textContent().then(s=>s.includes('100%')))throw Error('Wrong sound score')}
 await complete('greetings');await p.evaluate(()=>DEUTSCH_SOUNDS.show('listening'));await complete('words');await complete('dictation');await p.evaluate(()=>DEUTSCH_SOUNDS.show('listening'));const lesson=await p.evaluate(()=>DEUTSCH_COURSE_DATA.lessons[3].id);await p.selectOption('#soundLesson',lesson);await p.click('[data-sound-start="sentences"]');await p.evaluate(id=>{const q=DEUTSCH_SOUNDS.snapshot(),l=DEUTSCH_COURSE_DATA.lessons.find(l=>l.id===id);if(q.items.some(x=>!l.phrases.some(p=>p.de===x.de)))throw Error('Listening mixed lessons')},lesson);await p.evaluate(()=>DEUTSCH_SOUNDS.show('listening'));await complete('sentences');
 await p.evaluate(()=>{const s=DEUTSCH_SOUNDS.state();if(s.history.length!==4||s.history.some(h=>h.score!==100)||JSON.parse(profileStorage.getItem('deutsch16_course_v2'))['sounds-greetings'].best!==90)throw Error('Sound progress/migration failed');DEUTSCH_SOUNDS.start('words');setMode('home');DEUTSCH_SOUNDS.answer('stale');if(DEUTSCH_SOUNDS.snapshot())throw Error('Hidden quiz stayed active');DEUTSCH_FULL_COURSE.open('personal-pronouns');if(document.querySelector('[data-cv2-mode="listen"]'))throw Error('Listening remains in grammar mode selector')});
 for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});await p.click('#soundsTab');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+5))throw Error('Sound layout overflow '+width);await p.click('#homeTab');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+5))throw Error('Four-tab navigation overflow '+width)}
 await p.click('#profileButton');await p.fill('#profileAddInput','Окреме слухання');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);if(await p.evaluate(()=>DEUTSCH_SOUNDS.state().history.length||DEUTSCH_SOUNDS.state().legacyBest!=null))throw Error('Sound profile progress leaked');if(errors.length)throw Error(errors.join('; '));console.log('PASS 79 stable grammar lessons, collapsed accessible search, 22 recorded IPA topics, localized greetings/listening/dictation, lesson isolation, migration, profiles and 320–1280px');
 }finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
